// ──────────────────────────────────────────────
// CONFIG — edit these or override via env vars
// ──────────────────────────────────────────────
const GITHUB_OWNER  = $env.GITHUB_OWNER  || 'n8n-io';
const GITHUB_REPO   = $env.GITHUB_REPO   || 'n8n';
const SUMMARY_LANG  = $env.SUMMARY_LANG  || 'EN';   // EN or FR

const since = new Date();
since.setDate(since.getDate() - 7);
const sinceISO = since.toISOString();

return [
  {
    json: {
      GITHUB_OWNER,
      GITHUB_REPO,
      SUMMARY_LANG,
      since: sinceISO,
      weekStart: sinceISO.split('T')[0],
      weekEnd: new Date().toISOString().split('T')[0]
    }
  }
];

// Gather raw data from the three parallel GitHub API calls
const config   = $('Set Config Variables').first().json;
const sinceDate = new Date(config.since);

// ── Commits ──────────────────────────────────
let rawCommits = [];
try {
  const commitsData = $('Fetch Commits').first().json;
  rawCommits = Array.isArray(commitsData) ? commitsData : (commitsData ? [commitsData] : []);
} catch (e) { rawCommits = []; }

const commits = rawCommits.map(c => ({
  sha:     (c.sha || '').substring(0, 7),
  message: (c.commit?.message || '').split('\n')[0].substring(0, 120),
  author:  c.commit?.author?.name || c.author?.login || 'unknown',
  date:    c.commit?.author?.date || ''
}));

// ── Closed Issues (exclude PRs — they have pull_request key) ──
let rawIssues = [];
try {
  const issuesData = $('Fetch Closed Issues').first().json;
  rawIssues = Array.isArray(issuesData) ? issuesData : (issuesData ? [issuesData] : []);
} catch (e) { rawIssues = []; }

const closedIssues = rawIssues
  .filter(i => !i.pull_request)
  .filter(i => new Date(i.closed_at) >= sinceDate)
  .map(i => ({
    number: i.number,
    title:  (i.title || '').substring(0, 120),
    labels: (i.labels || []).map(l => l.name).join(', '),
    closedBy: i.user?.login || 'unknown'
  }));

// ── Merged PRs ───────────────────────────────
let rawPRs = [];
try {
  const prsData = $('Fetch Merged PRs').first().json;
  rawPRs = Array.isArray(prsData) ? prsData : (prsData ? [prsData] : []);
} catch (e) { rawPRs = []; }

const mergedPRs = rawPRs
  .filter(pr => pr.merged_at && new Date(pr.merged_at) >= sinceDate)
  .map(pr => ({
    number:  pr.number,
    title:   (pr.title || '').substring(0, 120),
    author:  pr.user?.login || 'unknown',
    labels:  (pr.labels || []).map(l => l.name).join(', '),
    additions: pr.additions || 0,
    deletions: pr.deletions || 0
  }));

// ── Unique contributors ──────────────────────
const contributors = [...new Set([
  ...commits.map(c => c.author),
  ...mergedPRs.map(pr => pr.author)
])];

// ── Check for empty week ─────────────────────
const isEmpty = commits.length === 0 && closedIssues.length === 0 && mergedPRs.length === 0;

// ── Truncate for Claude token limits (large repos) ──
const MAX_COMMITS = 50;
const MAX_ISSUES  = 50;
const MAX_PRS     = 50;
const truncatedCommits = commits.slice(0, MAX_COMMITS);
const truncatedIssues  = closedIssues.slice(0, MAX_ISSUES);
const truncatedPRs     = mergedPRs.slice(0, MAX_PRS);
const wasTruncated = commits.length > MAX_COMMITS || closedIssues.length > MAX_ISSUES || mergedPRs.length > MAX_PRS;

return [{
  json: {
    repo: `${config.GITHUB_OWNER}/${config.GITHUB_REPO}`,
    weekStart: config.weekStart,
    weekEnd: config.weekEnd,
    language: config.SUMMARY_LANG,
    isEmpty,
    wasTruncated,
    stats: {
      totalCommits:  commits.length,
      closedIssues:  closedIssues.length,
      mergedPRs:     mergedPRs.length,
      contributors:  contributors.length
    },
    commits:      truncatedCommits,
    closedIssues: truncatedIssues,
    mergedPRs:    truncatedPRs,
    contributors
  }
}];

const data = $('Aggregate & Format Data').first().json;
const lang = data.language || 'EN';

const msg = lang === 'FR'
  ? `## 📊 Résumé Hebdomadaire — ${data.repo}
**${data.weekStart} → ${data.weekEnd}**

_Aucune activité cette semaine. Pas de commits, issues fermées, ni PRs mergées._

🏖️ Semaine calme — bonne occasion de planifier le prochain sprint !`
  : `## 📊 Weekly Dev Summary — ${data.repo}
**${data.weekStart} → ${data.weekEnd}**

_No activity this week. Zero commits, closed issues, or merged PRs._

🏖️ Quiet week — great time to plan the next sprint!`;

return [{ json: { summary: msg } }];

const response = $('Claude Summarize').first().json;

// Handle Claude API response structure
let summary = '';

if (response.content && Array.isArray(response.content)) {
  summary = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (response.error) {
  // Claude API error — build a fallback summary from raw data
  const data = $('Aggregate & Format Data').first().json;
  summary = `## 📊 Weekly Dev Summary — ${data.repo}\n`
    + `**${data.weekStart} → ${data.weekEnd}**\n\n`
    + `⚠️ _AI summary unavailable (API error). Raw stats below._\n\n`
    + `**📈 Stats:** ${data.stats.totalCommits} commits | ${data.stats.closedIssues} issues closed | ${data.stats.mergedPRs} PRs merged | ${data.stats.contributors} contributors\n\n`
    + `**Recent commits:**\n`
    + data.commits.slice(0, 10).map(c => `• \`${c.sha}\` ${c.message} — _${c.author}_`).join('\n')
    + '\n\n'
    + `**Merged PRs:**\n`
    + data.mergedPRs.slice(0, 10).map(pr => `• #${pr.number} ${pr.title} — _${pr.author}_`).join('\n');
}

// Discord has a 2000 char limit per message
if (summary.length > 1950) {
  summary = summary.substring(0, 1947) + '...';
}

return [{ json: { summary } }];

const summary = $json.summary || 'No summary generated';
const sent = $('Send to Discord').first().json;
const success = !sent?.error;

return [{
  json: {
    status: success ? '✅ Summary delivered to Discord' : '⚠️ Discord delivery may have failed — check webhook URL',
    summaryLength: summary.length,
    timestamp: new Date().toISOString()
  }
}];
